        } else if (typeof left === 'string' && typeof right === 'string') {
          cmp = left < right ? -1 : (left > right ? 1 : 0)
        } else if (isBoolean(left) && isBoolean(right)) {
          const lv = left.value ? 1 : 0
          const rv = right.value ? 1 : 0
          cmp = lv < rv ? -1 : (lv > rv ? 1 : 0)
        } else {
          cmp = 0 // Same value
        }
      } else {
        cmp = leftPriority < rightPriority ? -1 : 1
      }

      const result = 
        ast.op === '=' ? cmp === 0 :
        ast.op === '<>' ? cmp !== 0 :
        ast.op === '<' ? cmp < 0 :
        ast.op === '<=' ? cmp <= 0 :
        ast.op === '>' ? cmp > 0 :
        ast.op === '>=' ? cmp >= 0 :
        false

      return createBoolean(result)
    }

    return createError('ERR')
  }

  if (ast.type === 'call') {
    return evaluateCall(ast.name, ast.args, sheet, evaluatedCells, visiting)
  }

  return createError('ERR')
}

function evaluateCell(col, row, sheet, evaluatedCells, visiting) {
  const key = `${col},${row}`

  // Check if already evaluated
  if (evaluatedCells.has(key)) {
    return evaluatedCells.get(key)
  }

  // Check for cycle
  if (visiting.has(key)) {
    return createError('CYCLE')
  }

  // Mark as visiting
  visiting.add(key)

  let value
  const cell = sheet.getCell(col, row)
  if (!cell) {
    // Undeclared cell is 0
    value = 0
  } else if (cell.isFormula) {
    // Evaluate formula
    const result = evaluateAST(cell.ast, sheet, evaluatedCells, visiting)
    value = result
  } else {
    // Parse literal
    value = parseLiteral(cell.content)
  }

  // Mark as visited (remove from visiting set)
  visiting.delete(key)

  // Cache the result
  evaluatedCells.set(key, value)
  return value
}

function parseLiteral(content) {
  if (content === '' || content === null) {
    return 0
  }

  // Check for error tokens
  const errorTokens = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
  if (errorTokens.includes(content)) {
    const code = content.substring(1, content.length - 1) // Remove # and !
    return createError(code)
  }

  // Check for boolean
  if (content === 'TRUE') {
    return createBoolean(true)
  }
  if (content === 'FALSE') {
    return createBoolean(false)
  }

  // Try to parse as number
  const num = parseFloat(content)
  if (!isNaN(num) && /^-?\d+(\.\d+)?$/.test(content.trim())) {
    return num
  }

  // Otherwise it's text
  return content
}

/**
 * Expand a range into an array of cell values
 */
function expandRange(range, sheet, evaluatedCells, visiting) {
  const values = []
  const startCol = Math.min(range.start.col, range.end.col)
  const endCol = Math.max(range.start.col, range.end.col)
  const startRow = Math.min(range.start.row, range.end.row)
  const endRow = Math.max(range.start.row, range.end.row)

  for (let col = startCol; col <= endCol; col++) {
    for (let row = startRow; row <= endRow; row++) {
      const value = evaluateCell(col, row, sheet, evaluatedCells, visiting)
      values.push(value)
    }
  }

  return values
}

/**
 * Get all cells referenced in an argument (for collecting dependencies)
 */
export function getReferencedCells(ast, sheet) {
  const cells = new Set()

  function traverse(node) {
    if (!node) return

    if (node.type === 'cell') {
      cells.add(`${node.col},${node.row}`)
    } else if (node.type === 'range') {
      const startCol = Math.min(node.start.col, node.end.col)
      const endCol = Math.max(node.start.col, node.end.col)
      const startRow = Math.min(node.start.row, node.end.row)
      const endRow = Math.max(node.start.row, node.end.row)

      for (let col = startCol; col <= endCol; col++) {
        for (let row = startRow; row <= endRow; row++) {
          cells.add(`${col},${row}`)
        }
      }
    } else if (node.type === 'unary') {
      traverse(node.expr)
    } else if (node.type === 'binop') {
      traverse(node.left)
      traverse(node.right)
    } else if (node.type === 'call') {
      for (const arg of node.args) {
        traverse(arg)
      }
    }
  }

  traverse(ast)
  return cells
}

/**
 * Evaluate a function call
 */
function evaluateCall(name, args, sheet, evaluatedCells, visiting) {
  const functions = {
    'SUM': evaluateSUM,
    'MIN': evaluateMIN,
    'MAX': evaluateMAX,
    'COUNT': evaluateCOUNT,
    'AVG': evaluateAVG,
    'ABS': evaluateABS,
    'IF': evaluateIF
  }

  if (!(name in functions)) {
    return createError('NAME')
  }

  return functions[name](args, sheet, evaluatedCells, visiting)
}

function evaluateSUM(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let sum = 0
  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    sum += values.numbers
  }

  return sum
}

function evaluateMIN(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let min = Infinity
  let found = false

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    if (values.list.length > 0) {
      found = true
      for (const v of values.list) {
        if (typeof v === 'number' && v < min) {
          min = v
        }
      }
    }
  }

  return found ? min : 0
}

function evaluateMAX(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let max = -Infinity
  let found = false

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    if (values.list.length > 0) {
      found = true
      for (const v of values.list) {
        if (typeof v === 'number' && v > max) {
          max = v
        }
      }
    }
  }

  return found ? max : 0
}

function evaluateCOUNT(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let count = 0

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting, true) // allowErrors=true
    if (values.list) {
      for (const v of values.list) {
        if (typeof v === 'number') {
          count++
        }
      }
    }
  }

  return count
}

function evaluateAVG(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let sum = 0
  let count = 0

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    for (const v of values.list) {
      if (typeof v === 'number') {
        sum += v
        count++
      }
    }
  }

  if (count === 0) return 0
  return sum / count
}

function evaluateABS(args, sheet, evaluatedCells, visiting) {
  if (args.length !== 1) return createError('ERR')

  const value = evaluateAST(args[0], sheet, evaluatedCells, visiting)
  if (isError(value)) return value

  const numResult = toNumber(value)
  if (numResult.error) return createError(numResult.error)

  return Math.abs(numResult.value)
}

function evaluateIF(args, sheet, evaluatedCells, visiting) {
  if (args.length !== 3) return createError('ERR')

  const condition = evaluateAST(args[0], sheet, evaluatedCells, visiting)
  if (isError(condition)) return condition

  // Determine truthiness
  let isTruthy
  if (isBoolean(condition)) {
    isTruthy = condition.value
  } else if (typeof condition === 'number') {
    isTruthy = condition !== 0
  } else if (typeof condition === 'string') {
    isTruthy = false
  } else {
    isTruthy = false
  }

  // Evaluate only the branch we take
  if (isTruthy) {
    return evaluateAST(args[1], sheet, evaluatedCells, visiting)
  } else {
    return evaluateAST(args[2], sheet, evaluatedCells, visiting)
  }
}

/**
 * Collect values from an argument (may be a range or expression)
 */
function collectValues(arg, sheet, evaluatedCells, visiting, allowErrors = false) {
  if (arg.type === 'range') {
    const values = expandRange(arg, sheet, evaluatedCells, visiting)
    // For non-COUNT functions, check for errors
    if (!allowErrors) {
      for (const v of values) {
        if (isError(v)) return { error: v }
        const numResult = toNumber(v)
        if (numResult.error) return { error: createError(numResult.error) }
      }
    }
    // Convert to numbers for non-COUNT functions
    if (!allowErrors) {
      const nums = []
      for (const v of values) {
        if (typeof v === 'number') nums.push(v)
        else if (isBoolean(v)) nums.push(v.value ? 1 : 0)
      }
      return { list: nums }
    }
    return { list: values }
  }

  const value = evaluateAST(arg, sheet, evaluatedCells, visiting)
  if (isError(value)) {
    if (allowErrors) return { list: [value] }
    return { error: value }
  }

  if (!allowErrors) {
    const numResult = toNumber(value)
    if (numResult.error) return { error: createError(numResult.error) }
    return { list: [numResult.value] }
  }

  return { list: [value] }
}
"}

