{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseInput, addressToString } from './parser.js'
import { Sheet } from './sheet.js'
import { evaluateAST, formatValue, getReferencedCells, isError } from './evaluator.js'

const mode = process.argv[2]

if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

// Read stdin
let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', chunk => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    // Parse input
    const { cells, errors } = parseInput(input)

    if (errors.length > 0) {
      const error = errors[0]
      process.stderr.write(`error: line ${error.line}: ${error.msg}\n`)
      process.exit(2)
    }

    // Create sheet and add cells
    const sheet = new Sheet()
    for (const { addr, content } of cells) {
      const isFormula = content.startsWith('=')
      const formulaBody = isFormula ? content.substring(1) : content
      sheet.setCell(addr.col, addr.row, formulaBody, isFormula)
    }

    // Get all declared cells in order
    const allCells = sheet.getAllCells()

    if (mode === 'values') {
      // Evaluate each cell and print its value
      const evaluatedCells = new Map()
      for (const { col, row } of allCells) {
        const cell = sheet.getCell(col, row)
        let value
        if (cell.isFormula) {
          value = evaluateAST(cell.ast, sheet, evaluatedCells, new Set())
        } else {
          // Parse literal
          value = parseLiteral(cell.content)
        }
        const address = addressToString(col, row)
        console.log(`${address}=${formatValue(value)}`)
      }
    } else if (mode === 'deps') {
      // Print dependencies for each cell
      for (const { col, row, cell } of allCells) {
        const address = addressToString(col, row)
        if (cell.isFormula && cell.ast) {
          const refs = getReferencedCells(cell.ast, sheet)
          const refArray = Array.from(refs)
            .map(key => {
              const [c, r] = key.split(',').map(Number)
              return { col: c, row: r, key }
            })
            .sort((a, b) => {
              if (a.col !== b.col) return a.col - b.col
              return a.row - b.row
            })
            .map(item => addressToString(item.col, item.row))

          if (refArray.length > 0) {
            console.log(`${address}: ${refArray.join(' ')}`)
          } else {
            console.log(`${address}:`)
          }
        } else {
          console.log(`${address}:`)
        }
      }
    }

    process.exit(0)
  } catch (err) {
    console.error('error:', err.message)
    process.exit(2)
  }
})

/**
 * Parse a literal value
 */
function parseLiteral(content) {
  if (content === '' || content === null) {
    return 0
  }

  // Check for error tokens
  const errorTokens = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
  if (errorTokens.includes(content)) {
    const code = content.substring(1, content.length - 1)
    return { type: 'error', code }
  }

  // Check for boolean
  if (content === 'TRUE') {
    return { type: 'boolean', value: true }
  }
  if (content === 'FALSE') {
    return { type: 'boolean', value: false }
  }

  // Try to parse as number
  const num = parseFloat(content)
  if (!isNaN(num) && /^-?\d+(\.\d+)?$/.test(content.trim())) {
    return num
  }

  // Otherwise it's text
  return content
}
"}

