{"file_path":"src/parser.js","content":"/**
 * Cell addresses and sheet input parsing.
 */

/**
 * Parse a cell address. Columns are one or two letters (A..ZZ), rows are one
 * to three digits naming a row of at least 1. Returns {col, row} (col 0-based)
 * or null when the text is not an address inside the addressable range.
 */
export function parseAddress(str) {
  if (typeof str !== 'string' || str.length === 0) return null

  const match = str.toUpperCase().match(/^([A-Z]{1,2})([0-9]{1,3})$/)
  if (!match) return null

  const row = parseInt(match[2], 10)
  if (row < 1) return null

  let col = 0
  for (const ch of match[1]) col = col * 26 + (ch.charCodeAt(0) - 64)
  col--

  return { col, row }
}

function colToString(col) {
  let out = ''
  let n = col + 1
  while (n > 0) {
    n--
    out = String.fromCharCode(65 + (n % 26)) + out
    n = Math.floor(n / 26)
  }
  return out
}

export function addressToString(col, row) {
  return colToString(col) + row
}

/**
 * Split the sheet into cells. Returns {cells, error} where error, when set, is
 * {line, msg}; parsing stops at the first failure.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = []
  const seen = new Set()

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line.length === 0 || line[0] === '#') continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++

    const addrStr = line.slice(0, end)
    const addr = parseAddress(addrStr)
    if (!addr) {
      return { cells: [], error: { line: i + 1, msg: `invalid cell address ${addrStr}` } }
    }

    const key = `${addr.col},${addr.row}`
    if (seen.has(key)) {
      return {
        cells: [],
        error: {
          line: i + 1,
          msg: `cell ${addressToString(addr.col, addr.row)} is declared twice`
        }
      }
    }
    seen.add(key)

    let start = end
    while (start < line.length && (line[start] === ' ' || line[start] === '\t')) start++

    cells.push({ addr, content: line.slice(start) })
  }

  return { cells, error: null }
}
"}

