/**
 * Parser for cell addresses, input lines, and formulas
 */

/**
 * Parse a cell address string (e.g., "A1", "AA99")
 * @returns {{col: number, row: number}} or null if invalid
 */
export function parseAddress(str) {
  if (typeof str !== 'string' || str.length === 0) return null

  const upper = str.toUpperCase()
  // Match 1-2 letters followed by 1-3 digits
  const match = upper.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return null

  const colStr = match[1]
  const rowStr = match[2]
  const row = parseInt(rowStr, 10)

  // Row must be between 1 and 999
  if (row < 1 || row > 999) return null

  // Convert column letters to number (A=0, B=1, ..., Z=25, AA=26, etc.)
  let col = 0
  for (let i = 0; i < colStr.length; i++) {
    col = col * 26 + (colStr.charCodeAt(i) - 65 + 1)
  }
  col-- // Convert to 0-based

  // Only A-Z (0-25) and AA-ZZ (26-701) are valid
  if (col < 0 || col > 701) return null

  return { col, row }
}

/**
 * Convert column number to letter(s)
 */
function colToString(col) {
  let result = ''
  col += 1 // Convert to 1-based for calculation
  while (col > 0) {
    col-- // Adjust to 0-based for modulo
    result = String.fromCharCode(65 + (col % 26)) + result
    col = Math.floor(col / 26)
  }
  return result
}

/**
 * Convert {col, row} to address string
 */
export function addressToString(col, row) {
  return colToString(col) + row
}

/**
 * Parse input lines into cells
 * Returns {cells: [{addr: {col, row}, content: string}], errors: [{line, msg}]}
 */
export function parseInput(input) {
  const lines = input.split('\n')
  // Remove trailing empty string from split
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = []
  const errors = []
  const seenAddresses = new Set()

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    // Strip leading spaces and tabs
    const stripped = line.replace(/^[ \t]+/, '')

    // Skip empty lines and comments
    if (stripped.length === 0 || stripped[0] === '#') continue

    // Find the address (next space/tab or end of line)
    let addrEnd = 0
    while (addrEnd < stripped.length && stripped[addrEnd] !== ' ' && stripped[addrEnd] !== '\t') {
      addrEnd++
    }

    const addrStr = stripped.substring(0, addrEnd)
    const addr = parseAddress(addrStr)

    if (!addr) {
      errors.push({ line: lineNum + 1, msg: `invalid cell address ${addrStr}` })
      return { cells: [], errors }
    }

    // Check for duplicate
    const addrKey = `${addr.col},${addr.row}`
    if (seenAddresses.has(addrKey)) {
      errors.push({ line: lineNum + 1, msg: `cell ${addressToString(addr.col, addr.row)} is declared twice` })
      return { cells: [], errors }
    }
    seenAddresses.add(addrKey)

    // Skip one run of spaces/tabs
    let contentStart = addrEnd
    if (contentStart < stripped.length && (stripped[contentStart] === ' ' || stripped[contentStart] === '\t')) {
      contentStart++
      while (contentStart < stripped.length && (stripped[contentStart] === ' ' || stripped[contentStart] === '\t')) {
        contentStart++
      }
    }

    const content = stripped.substring(contentStart)
    cells.push({ addr, content })
  }

  return { cells, errors }
}

/**
 * Tokenize a formula for parsing
 */
export function tokenizeFormula(formula) {
  const tokens = []
  let i = 0

  while (i < formula.length) {
    // Skip whitespace
    if (formula[i] === ' ' || formula[i] === '\t') {
      i++
      continue
    }

    // Numbers
    if (formula[i] >= '0' && formula[i] <= '9') {
      let j = i
      while (j < formula.length && formula[j] >= '0' && formula[j] <= '9') j++
      if (j < formula.length && formula[j] === '.') {
        j++
        while (j < formula.length && formula[j] >= '0' && formula[j] <= '9') j++
      }
      tokens.push({ type: 'number', value: formula.substring(i, j) })
      i = j
      continue
    }

    // Identifiers and keywords (cell addresses, function names, TRUE, FALSE)
    if ((formula[i] >= 'a' && formula[i] <= 'z') || (formula[i] >= 'A' && formula[i] <= 'Z')) {
      let j = i
      while (j < formula.length && ((formula[j] >= 'a' && formula[j] <= 'z') || (formula[j] >= 'A' && formula[j] <= 'Z') || (formula[j] >= '0' && formula[j] <= '9'))) {
        j++
      }
      const ident = formula.substring(i, j).toUpperCase()

      // Check for range (address:address)
      if (j < formula.length && formula[j] === ':') {
        // This could be a range, but we need to defer to the parser
        tokens.push({ type: 'ident', value: ident })
        i = j
        continue
      }

      tokens.push({ type: 'ident', value: ident })
      i = j
      continue
    }

    // Operators and delimiters
    if (formula[i] === '(') {
      tokens.push({ type: 'lparen', value: '(' })
      i++
      continue
    }
    if (formula[i] === ')') {
      tokens.push({ type: 'rparen', value: ')' })
      i++
      continue
    }
    if (formula[i] === ':') {
      tokens.push({ type: 'colon', value: ':' })
      i++
      continue
    }
    if (formula[i] === ',') {
      tokens.push({ type: 'comma', value: ',' })
      i++
      continue
    }

    // Two-character operators
    if (i + 1 < formula.length) {
      const twoChar = formula.substring(i, i + 2)
      if (['<>', '<=', '>='].includes(twoChar)) {
        tokens.push({ type: 'op', value: twoChar })
        i += 2
        continue
      }
    }

    // Single-character operators
    if ('=<>+-*^/'.includes(formula[i])) {
      tokens.push({ type: 'op', value: formula[i] })
      i++
      continue
    }

    // Unknown character - will be caught by parser
    tokens.push({ type: 'unknown', value: formula[i] })
    i++
  }

  return tokens
}

