 * Tokenizer and parser for formula bodies.
 *
 * The grammar accepts numbers, words, ranges, calls, parentheses and the
 * operators. Anything it does not accept yields a null AST, which the caller
 * turns into #ERR!.
 */

import { parseAddress } from './parser.js'

export const FUNCTIONS = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']

const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/

export function tokenize(body) {
  const tokens = []
  let i = 0

  while (i < body.length) {
    const ch = body[i]

    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }

    if (DIGIT.test(ch)) {
      let j = i
      while (j < body.length && DIGIT.test(body[j])) j++
      if (j < body.length && body[j] === '.') {
        if (j + 1 < body.length && DIGIT.test(body[j + 1])) {
          j++
          while (j < body.length && DIGIT.test(body[j])) j++
        } else {
          return null // a dot with no digits after it is not a number
        }
      }
      tokens.push({ type: 'number', value: body.slice(i, j) })
      i = j
      continue
    }

    if (LETTER.test(ch)) {
      let j = i
      while (j < body.length && (LETTER.test(body[j]) || DIGIT.test(body[j]))) j++
      tokens.push({ type: 'word', value: body.slice(i, j).toUpperCase() })
      i = j
      continue
    }

    if (ch === '(') { tokens.push({ type: 'lparen' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'rparen' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'comma' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'colon' }); i++; continue }

    const two = body.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }

    if ('^*/+-=<>'.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i++
      continue
    }

    return null // character the grammar does not accept
  }

  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

/**
 * Parse a formula body. Returns the AST, or null when the grammar rejects it.
 */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null

  let pos = 0
  let failed = false

  const peek = () => (pos < tokens.length ? tokens[pos] : null)

  function fail() {
    failed = true
    return null
  }

  function eat(type) {
    const t = peek()
    if (!t || t.type !== type) return null
    pos++
    return t
  }

  function parseExpr() {
    let left = parseAdditive()
    if (failed) return null
    for (;;) {
      const t = peek()
      if (!t || t.type !== 'op' || !COMPARISONS.includes(t.value)) break
      pos++
      const right = parseAdditive()
      if (failed) return null
      left = { type: 'binop', op: t.value, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    if (failed) return null
    for (;;) {
      const t = peek()
      if (!t || t.type !== 'op' || (t.value !== '+' && t.value !== '-')) break
      pos++
      const right = parseMultiplicative()
      if (failed) return null
      left = { type: 'binop', op: t.value, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    if (failed) return null
    for (;;) {
      const t = peek()
      if (!t || t.type !== 'op' || (t.value !== '*' && t.value !== '/')) break
      pos++
      const right = parsePower()
      if (failed) return null
      left = { type: 'binop', op: t.value, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (failed) return null
    const t = peek()
    if (t && t.type === 'op' && t.value === '^') {
      pos++
      const right = parsePower() // right associative
      if (failed) return null
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  function parseUnary() {
    const t = peek()
    if (t && t.type === 'op' && (t.value === '+' || t.value === '-')) {
      pos++
      const operand = parseUnary()
      if (failed) return null
      return { type: 'unary', op: t.value, operand }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()
    if (!t) return fail()

    if (t.type === 'number') {
      pos++
      return { type: 'number', value: parseFloat(t.value) }
    }

    if (t.type === 'lparen') {
      pos++
      const inner = parseExpr()
      if (failed) return null
      if (!eat('rparen')) return fail()
      return inner
    }

    if (t.type === 'word') {
      pos++
      const word = t.value
      const next = peek()

      if (next && next.type === 'lparen') {
        pos++
        const args = []
        if (peek() && peek().type === 'rparen') {
          pos++
        } else {
          for (;;) {
            const arg = parseExpr()
            if (failed) return null
            args.push(arg)
            if (eat('comma')) continue
            if (!eat('rparen')) return fail()
            break
          }
        }
        return { type: 'call', name: word, args }
      }

      if (next && next.type === 'colon') {
        pos++
        const endTok = eat('word')
        if (!endTok) return fail()
        return { type: 'range', start: parseAddress(word), end: parseAddress(endTok.value) }
      }

      if (word === 'TRUE') return { type: 'boolean', value: true }
      if (word === 'FALSE') return { type: 'boolean', value: false }

      const addr = parseAddress(word)
      if (addr) return { type: 'cell', col: addr.col, row: addr.row }
      return { type: 'badref' }
    }

    return fail()
  }

  const ast = parseExpr()
  if (failed || ast === null) return null
  if (pos !== tokens.length) return null
  return ast
}
