/**
 * Parser for formula expressions
 */

import { parseAddress, addressToString, tokenizeFormula } from './parser.js'

/**
 * Parse a formula into an AST
 * Returns {ast, errors} where errors is array of error messages or empty
 */
export function parseFormula(formula) {
  const tokens = tokenizeFormula(formula)
  let pos = 0

  function peek() {
    return pos < tokens.length ? tokens[pos] : null
  }

  function consume() {
    return tokens[pos++]
  }

  function expect(type, value = null) {
    const token = peek()
    if (!token || token.type !== type || (value !== null && token.value !== value)) {
      return null
    }
    return consume()
  }

  function parseExpr() {
    return parseComparison()
  }

  function parseComparison() {
    let left = parseAdditive()
    if (!left) return null

    while (peek() && peek().type === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().value)) {
      const op = consume()
      const right = parseAdditive()
      if (!right) return null
      left = { type: 'binop', op: op.value, left, right }
    }

    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    if (!left) return null

    while (peek() && peek().type === 'op' && ['+', '-'].includes(peek().value)) {
      const op = consume()
      const right = parseMultiplicative()
      if (!right) return null
      left = { type: 'binop', op: op.value, left, right }
    }

    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    if (!left) return null

    while (peek() && peek().type === 'op' && ['*', '/', '%'].includes(peek().value)) {
      const op = consume()
      const right = parsePower()
      if (!right) return null
      left = { type: 'binop', op: op.value, left, right }
    }

    return left
  }

  function parsePower() {
    let left = parseUnary()
    if (!left) return null

    // Right-associative
    if (peek() && peek().type === 'op' && peek().value === '^') {
      const op = consume()
      const right = parsePower() // Right-associative recursion
      if (!right) return null
      left = { type: 'binop', op: op.value, left, right }
    }

    return left
  }

  function parseUnary() {
    if (peek() && peek().type === 'op' && ['+', '-'].includes(peek().value)) {
      const op = consume()
      const expr = parseUnary()
      if (!expr) return null
      return { type: 'unary', op: op.value, expr }
    }

    return parsePrimary()
  }

  function parsePrimary() {
    let token = peek()

    if (!token) return null

    // Numbers
    if (token.type === 'number') {
      consume()
      return { type: 'number', value: token.value }
    }

    // Parentheses
    if (token.type === 'lparen') {
      consume()
      const expr = parseExpr()
      if (!expr) return null
      if (!expect('rparen')) return null
      return expr
    }

    // Identifiers (function calls, TRUE, FALSE, cell addresses)
    if (token.type === 'ident') {
      const ident = consume()
      const upper = ident.value.toUpperCase()

      // Boolean literals
      if (upper === 'TRUE') {
        return { type: 'boolean', value: true }
      }
      if (upper === 'FALSE') {
        return { type: 'boolean', value: false }
      }

      // Function calls
      if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(upper)) {
        if (!expect('lparen')) return null

        const args = []
        if (peek() && peek().type !== 'rparen') {
          // Parse arguments - ranges are allowed here
          while (true) {
            const arg = parseFunctionArgument()
            if (!arg) return null
            args.push(arg)

            if (expect('comma')) {
              continue
            } else {
              break
            }
          }
        }

        if (!expect('rparen')) return null
        return { type: 'call', name: upper, args }
      }

      // Check if this might be an unknown function call
      if (peek() && peek().type === 'lparen') {
        consume() // consume the lparen

        const args = []
        if (peek() && peek().type !== 'rparen') {
          while (true) {
            const arg = parseFunctionArgument()
            if (!arg) return null
            args.push(arg)

            if (expect('comma')) {
              continue
            } else {
              break
            }
          }
        }

        if (!expect('rparen')) return null
        // Unknown function
        return { type: 'call', name: upper, args }
      }

      // Cell address (not a function call)
      const addr = parseAddress(ident.value)
      if (addr) {
        return { type: 'cell', col: addr.col, row: addr.row }
      }

      // Unknown identifier - treat as name for error handling
      return { type: 'name', value: ident.value }
    }

    return null
  }

  function parseFunctionArgument() {
    // Parse either a range or an expression
    // First, try to parse an identifier for potential range
    if (peek() && peek().type === 'ident') {
      const startPos = pos
      const ident = consume()
      const addr = parseAddress(ident.value)

      if (addr && peek() && peek().type === 'colon') {
        // This is a range
        consume() // consume the colon
        const nextIdent = expect('ident')
        if (!nextIdent) return null
        const endAddr = parseAddress(nextIdent.value)
        if (!endAddr) return null
        return { type: 'range', start: addr, end: endAddr }
      } else {
        // Not a range, back up and parse as expression
        pos = startPos
        return parseExpr()
      }
    }

    return parseExpr()
  }

  const ast = parseExpr()
  if (!ast) {
    return { ast: null, errors: ['Parse error'] }
  }

  // Check if we consumed all tokens
  if (pos !== tokens.length) {
    return { ast: null, errors: ['Parse error - unconsumed tokens'] }
  }

  return { ast, errors: [] }
}

