      if (failed) return null
      left = { type: 'binop', op: t.value, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (failed) return null
    const t = peek()
    if (t && t.type === 'op' && t.value === '^') {
      pos++
      const right = parsePower() // right associative
      if (failed) return null
      return { type: 'binop', op: '^', left, right }
