      pos++
      const operand = parseUnary()
      if (failed) return null
      return { type: 'unary', op: t.value, operand }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()
    if (!t) return fail()

    if (t.type === 'number') {
      pos++
      return { type: 'number', value: parseFloat(t.value) }
    }

    if (t.type === 'lparen') {
      pos++
      const inner = parseExpr()
      if (failed) return null
      if (!eat('rparen')) return fail()
      return inner
    }

    if (t.type === 'word') {
      pos++
