import { FUNCTIONS } from './formula-parser.js'

export const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const err = (token) => ({ err: token })
export const bool = (value) => ({ bool: value })

export const isErr = (v) => typeof v === 'object' && v !== null && 'err' in v
export const isBool = (v) => typeof v === 'object' && v !== null && 'bool' in v
export const isNum = (v) => typeof v === 'number'
export const isText = (v) => typeof v === 'string'

const DIV0 = '#DIV/0!'
const REF = '#REF!'
const VALUE = '#VALUE!'
const CYCLE = '#CYCLE!'
const NAME = '#NAME?'
const ERR = '#ERR!'

export function formatValue(v) {
  if (isErr(v)) return v.err
  if (isBool(v)) return v.bool ? 'TRUE' : 'FALSE'
  if (isNum(v)) return formatNumber(v)
  return v
}

function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

/** The value of a literal cell content. */
export function parseLiteral(content) {
  if (content === '') return 0
  if (ERRORS.includes(content)) return err(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return Number(content)
  return content
}

function toNumber(v) {
  if (isErr(v)) return v
  if (isBool(v)) return v.bool ? 1 : 0
  if (isNum(v)) return v
  return err(VALUE)
}

function finite(n) {
  return Number.isFinite(n) ? n : err(DIV0)
}

function codePointCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const cx = x[i].codePointAt(0)
    const cy = y[i].codePointAt(0)
    if (cx !== cy) return cx < cy ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

function kindRank(v) {
  if (isNum(v)) return 0
  if (isText(v)) return 1
  return 2 // boolean
}

function compare(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ra === 1) return codePointCompare(a, b)
  const x = a.bool ? 1 : 0
  const y = b.bool ? 1 : 0
  return x < y ? -1 : x > y ? 1 : 0
}

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.visiting = new Set()
  }

  cellValue(col, row) {
    const key = `${col},${row}`
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.visiting.has(key)) return err(CYCLE)

    const cell = this.sheet.get(col, row)
    let value
    if (!cell) {
      value = 0
    } else if (cell.formula) {
      this.visiting.add(key)
      value = cell.ast === null ? err(ERR) : this.evalNode(cell.ast)
      this.visiting.delete(key)
    } else {
      value = parseLiteral(cell.content)
    }

    this.cache.set(key, value)
    return value
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return node.value
      case 'boolean':
        return bool(node.value)
      case 'cell':
        return this.cellValue(node.col, node.row)
      case 'badref':
        return err(REF)
      case 'range':
        return err(ERR) // a range anywhere but directly as an argument
      case 'unary': {
        const v = this.evalNode(node.operand)
        if (isErr(v)) return v
        const n = toNumber(v)
        if (isErr(n)) return n
        return node.op === '-' ? finite(-n) : finite(n)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        return err(ERR)
    }
  }

  evalBinop(node) {
    const left = this.evalNode(node.left)
    const right = this.evalNode(node.right)
    if (isErr(left)) return left
    if (isErr(right)) return right

    if (COMPARISON_OPS.includes(node.op)) {
      const c = compare(left, right)
      switch (node.op) {
        case '=': return bool(c === 0)
        case '<>': return bool(c !== 0)
        case '<': return bool(c < 0)
        case '<=': return bool(c <= 0)
        case '>': return bool(c > 0)
        default: return bool(c >= 0)
      }
    }

    const a = toNumber(left)
    if (isErr(a)) return a
    const b = toNumber(right)
    if (isErr(b)) return b

    switch (node.op) {
      case '+': return finite(a + b)
      case '-': return finite(a - b)
      case '*': return finite(a * b)
      case '/': return b === 0 ? err(DIV0) : finite(a / b)
      case '^': return finite(Math.pow(a, b))
      default: return err(ERR)
    }
  }

  /** The values an argument contributes, in order; a range expands. */
  argValues(node) {
    if (node.type === 'range') {
      if (!node.start || !node.end) return [err(REF)]
      const c0 = Math.min(node.start.col, node.end.col)
      const c1 = Math.max(node.start.col, node.end.col)
      const r0 = Math.min(node.start.row, node.end.row)
      const r1 = Math.max(node.start.row, node.end.row)
      const out = []
      for (let c = c0; c <= c1; c++) {
        for (let r = r0; r <= r1; r++) out.push(this.cellValue(c, r))
      }
      return out
    }
    return [this.evalNode(node)]
  }

  collect(args) {
    const values = []
    for (const arg of args) {
      for (const v of this.argValues(arg)) {
        if (isErr(v)) return { error: v }
        values.push(v)
      }
    }
    return { values }
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.includes(name)) return err(NAME)

    const n = node.args.length
    if (name === 'ABS' && n !== 1) return err(ERR)
    if (name === 'IF' && n !== 3) return err(ERR)
    if (name !== 'ABS' && name !== 'IF' && n < 1) return err(ERR)

    if (name === 'IF') return this.evalIf(node.args)

    const collected = this.collect(node.args)
    if (collected.error) return collected.error
    const values = collected.values

    if (name === 'COUNT') {
      let count = 0
      for (const v of values) if (isNum(v)) count++
      return count
    }

    const numbers = []
    for (const v of values) {
      const x = toNumber(v)
      if (isErr(x)) return x
      numbers.push(x)
    }

    switch (name) {
      case 'SUM': {
        let sum = 0
        for (const x of numbers) sum += x
        return finite(sum)
      }
      case 'MIN': {
        let best = numbers[0]
        for (const x of numbers) if (x < best) best = x
        return best
      }
      case 'MAX': {
        let best = numbers[0]
        for (const x of numbers) if (x > best) best = x
        return best
      }
      case 'AVG': {
        let sum = 0
        for (const x of numbers) sum += x
        if (numbers.length === 0) return err(DIV0)
        return finite(sum / numbers.length)
      }
      case 'ABS': {
        if (numbers.length !== 1) return err(VALUE)
        return finite(Math.abs(numbers[0]))
      }
      default:
        return err(ERR)
    }
  }

  evalIf(args) {
    const condValues = this.argValues(args[0])
    for (const v of condValues) if (isErr(v)) return v
    if (condValues.length !== 1) return err(VALUE)

    const cond = condValues[0]
    let truthy
    if (isBool(cond)) truthy = cond.bool
    else if (isNum(cond)) truthy = cond !== 0
    else return err(VALUE)

    const branch = truthy ? args[1] : args[2]
    const values = this.argValues(branch)
    for (const v of values) if (isErr(v)) return v
    if (values.length !== 1) return err(VALUE)
    return values[0]
  }
}

const COMPARISON_OPS = ['=', '<>', '<', '<=', '>', '>=']

/** The distinct in-range cells a formula names directly, ranges expanded. */
export function referencedCells(ast) {
  const keys = new Set()

  const walk = (node) => {
    if (!node) return
    switch (node.type) {
      case 'cell':
        keys.add(`${node.col},${node.row}`)
        break
      case 'range': {
        if (!node.start || !node.end) break
        const c0 = Math.min(node.start.col, node.end.col)
        const c1 = Math.max(node.start.col, node.end.col)
        const r0 = Math.min(node.start.row, node.end.row)
        const r1 = Math.max(node.start.row, node.end.row)
        for (let c = c0; c <= c1; c++) {
          for (let r = r0; r <= r1; r++) keys.add(`${c},${r}`)
        }
        break
      }
      case 'unary':
        walk(node.operand)
        break
      case 'binop':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }

  walk(ast)

  return Array.from(keys)
    .map((k) => {
      const [col, row] = k.split(',').map(Number)
      return { col, row }
    })
    .sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
}
