  if (isBool(v)) return v.bool ? 'TRUE' : 'FALSE'
  if (isNum(v)) return formatNumber(v)
  return v
}

function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

/** The value of a literal cell content. */
export function parseLiteral(content) {
  if (content === '') return 0
  if (ERRORS.includes(content)) return err(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return Number(content)
  return content
}

function toNumber(v) {
  if (isErr(v)) return v
  if (isBool(v)) return v.bool ? 1 : 0
  if (isNum(v)) return v
  return err(VALUE)
}

function finite(n) {
  return Number.isFinite(n) ? n : err(DIV0)
}

function codePointCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const cx = x[i].codePointAt(0)
    const cy = y[i].codePointAt(0)
    if (cx !== cy) return cx < cy ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

function kindRank(v) {
  if (isNum(v)) return 0
  if (isText(v)) return 1
  return 2 // boolean
}

function compare(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ra === 1) return codePointCompare(a, b)
  const x = a.bool ? 1 : 0
  const y = b.bool ? 1 : 0
  return x < y ? -1 : x > y ? 1 : 0
}

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.visiting = new Set()
  }

  cellValue(col, row) {
    const key = `${col},${row}`
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.visiting.has(key)) return err(CYCLE)

    const cell = this.sheet.get(col, row)
    let value
    if (!cell) {
      value = 0
    } else if (cell.formula) {
      this.visiting.add(key)
      value = cell.ast === null ? err(ERR) : this.evalNode(cell.ast)
      this.visiting.delete(key)
    } else {
      value = parseLiteral(cell.content)
    }

    this.cache.set(key, value)
    return value
  }

