      case 'unary': {
        const v = this.evalNode(node.operand)
        if (isErr(v)) return v
        const n = toNumber(v)
        if (isErr(n)) return n
        return node.op === '-' ? finite(-n) : finite(n)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        return err(ERR)
    }
  }

  evalBinop(node) {
    const left = this.evalNode(node.left)
    const right = this.evalNode(node.right)
    if (isErr(left)) return left
    if (isErr(right)) return right

    if (COMPARISON_OPS.includes(node.op)) {
      const c = compare(left, right)
      switch (node.op) {
        case '=': return bool(c === 0)
        case '<>': return bool(c !== 0)
        case '<': return bool(c < 0)
        case '<=': return bool(c <= 0)
        case '>': return bool(c > 0)
        default: return bool(c >= 0)
      }
    }

    const a = toNumber(left)
    if (isErr(a)) return a
    const b = toNumber(right)
    if (isErr(b)) return b

    switch (node.op) {
      case '+': return finite(a + b)
      case '-': return finite(a - b)
      case '*': return finite(a * b)
      case '/': return b === 0 ? err(DIV0) : finite(a / b)
      case '^': return finite(Math.pow(a, b))
      default: return err(ERR)
    }
