  collect(args) {
    const values = []
    for (const arg of args) {
      for (const v of this.argValues(arg)) {
        if (isErr(v)) return { error: v }
        values.push(v)
      }
    }
    return { values }
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.includes(name)) return err(NAME)

    const n = node.args.length
    if (name === 'ABS' && n !== 1) return err(ERR)
    if (name === 'IF' && n !== 3) return err(ERR)
    if (name !== 'ABS' && name !== 'IF' && n < 1) return err(ERR)

    if (name === 'IF') return this.evalIf(node.args)

    const collected = this.collect(node.args)
    if (collected.error) return collected.error
    const values = collected.values

    if (name === 'COUNT') {
      let count = 0
      for (const v of values) if (isNum(v)) count++
      return count
    }

    const numbers = []
    for (const v of values) {
      const x = toNumber(v)
      if (isErr(x)) return x
      numbers.push(x)
    }

    switch (name) {
      case 'SUM': {
        let sum = 0
        for (const x of numbers) sum += x
        return finite(sum)
      }
      case 'MIN': {
        let best = numbers[0]
        for (const x of numbers) if (x < best) best = x
        return best
      }
      case 'MAX': {
        let best = numbers[0]
        for (const x of numbers) if (x > best) best = x
        return best
      }
      case 'AVG': {
        let sum = 0
        for (const x of numbers) sum += x
        if (numbers.length === 0) return err(DIV0)
        return finite(sum / numbers.length)
      }
      case 'ABS': {
        if (numbers.length !== 1) return err(VALUE)
        return finite(Math.abs(numbers[0]))
      }
      default:
        return err(ERR)
    }
  }

  evalIf(args) {
    const condValues = this.argValues(args[0])
    for (const v of condValues) if (isErr(v)) return v
    if (condValues.length !== 1) return err(VALUE)

    const cond = condValues[0]
    let truthy
    if (isBool(cond)) truthy = cond.bool
    else if (isNum(cond)) truthy = cond !== 0
    else return err(VALUE)

    const branch = truthy ? args[1] : args[2]
    const values = this.argValues(branch)
    for (const v of values) if (isErr(v)) return v
    if (values.length !== 1) return err(VALUE)
    return values[0]
  }
