const COMPARISON_OPS = ['=', '<>', '<', '<=', '>', '>=']

/** The distinct in-range cells a formula names directly, ranges expanded. */
export function referencedCells(ast) {
  const keys = new Set()

  const walk = (node) => {
    if (!node) return
    switch (node.type) {
      case 'cell':
        keys.add(`${node.col},${node.row}`)
        break
      case 'range': {
        if (!node.start || !node.end) break
        const c0 = Math.min(node.start.col, node.end.col)
        const c1 = Math.max(node.start.col, node.end.col)
        const r0 = Math.min(node.start.row, node.end.row)
        const r1 = Math.max(node.start.row, node.end.row)
        for (let c = c0; c <= c1; c++) {
          for (let r = r0; r <= r1; r++) keys.add(`${c},${r}`)
        }
        break
      }
      case 'unary':
        walk(node.operand)
        break
      case 'binop':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }

  walk(ast)

  return Array.from(keys)
    .map((k) => {
      const [col, row] = k.split(',').map(Number)
      return { col, row }
    })
    .sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
}
