/**
 * Evaluator for formulas and cells
 */

import { addressToString } from './parser.js'

/**
 * Value types and error handling
 */

const ERROR_TOKENS = {
  'DIV/0': '#DIV/0!',
  'REF': '#REF!',
  'VALUE': '#VALUE!',
  'CYCLE': '#CYCLE!',
  'NAME': '#NAME?',
  'ERR': '#ERR!'
}

export function isError(value) {
  return typeof value === 'object' && value !== null && value.type === 'error'
}

export function isBoolean(value) {
  return typeof value === 'object' && value !== null && value.type === 'boolean'
}

export function isNumber(value) {
  return typeof value === 'number' && isFinite(value)
}

export function createError(code) {
  return { type: 'error', code }
}

export function createBoolean(value) {
  return { type: 'boolean', value }
}

/**
 * Format a value for output
 */
export function formatValue(value) {
  if (isError(value)) {
    return ERROR_TOKENS[value.code] || '#ERR!'
  }
  if (isBoolean(value)) {
    return value.value ? 'TRUE' : 'FALSE'
  }
  if (typeof value === 'number') {
    // Round to 10 significant digits
    return roundToSignificantDigits(value)
  }
  return String(value)
}

function roundToSignificantDigits(num, digits = 10) {
  if (num === 0) return '0'
  if (!isFinite(num)) return '#DIV/0!'

  const sign = num < 0 ? -1 : 1
  const abs = Math.abs(num)

  // Find the order of magnitude
  const magnitude = Math.floor(Math.log10(abs))
  const scale = Math.pow(10, digits - magnitude - 1)
  const rounded = Math.round(abs * scale) / scale

  // Format the number
  let str = (sign * rounded).toString()

  // Remove trailing zeros after decimal point
  if (str.includes('.')) {
    str = str.replace(/\.?0+$/, '')
  }

  return str
}

/**
 * Coerce value to number for arithmetic
 * Returns {value: number} or {error: errorCode}
 */
function toNumber(value) {
  if (isError(value)) {
    return { error: value.code }
  }
  if (isBoolean(value)) {
    return { value: value.value ? 1 : 0 }
  }
  if (typeof value === 'number') {
    return { value }
  }
  if (typeof value === 'string') {
    if (value === '') return { value: 0 }
    return { error: 'VALUE' }
  }
  return { error: 'VALUE' }
}

/**
 * Coerce value to number for comparison
 */
function toNumberForComparison(value) {
  if (isError(value)) {
    return null // error
  }
  if (isBoolean(value)) {
    return value.value ? 1 : 0
  }
  if (typeof value === 'number') {
    return value
  }
  return null
}

/**
 * Get comparison priority (for cross-type comparisons)
 */
function getComparisonPriority(value) {
  if (typeof value === 'number') return 0
  if (typeof value === 'string') return 1
  if (isBoolean(value)) return 2
  if (isError(value)) return -1
  return -1
}

/**
 * Evaluate an AST node
 */
export function evaluateAST(ast, sheet, evaluatedCells = new Map(), visiting = new Set()) {
  if (!ast) {
    return createError('ERR')
  }

  if (ast.type === 'number') {
    const num = parseFloat(ast.value)
    return isFinite(num) ? num : createError('ERR')
  }

  if (ast.type === 'boolean') {
    return createBoolean(ast.value)
  }

  if (ast.type === 'cell') {
    return evaluateCell(ast.col, ast.row, sheet, evaluatedCells, visiting)
  }

  if (ast.type === 'range') {
    // Ranges should only appear as function arguments
    // If we encounter one here, it's an error
    return createError('ERR')
  }

  if (ast.type === 'name') {
    // Unknown identifier - treated as attempted cell address
    // Per spec: "one that is not one or two letters and one to three digits 
    // naming a row of at least 1 — AAA1, A1000, A0 and FOO alike — 
    // is an address outside the addressable range rather than a grammar failure"
    return createError('REF')
  }

  if (ast.type === 'unary') {
    const expr = evaluateAST(ast.expr, sheet, evaluatedCells, visiting)
    if (isError(expr)) return expr

    if (ast.op === '-') {
      const numResult = toNumber(expr)
      if (numResult.error) return createError(numResult.error)
      return -numResult.value
    } else if (ast.op === '+') {
      const numResult = toNumber(expr)
      if (numResult.error) return createError(numResult.error)
      return numResult.value
    }
    return createError('ERR')
  }

  if (ast.type === 'binop') {
    // Handle errors - left error wins
    const left = evaluateAST(ast.left, sheet, evaluatedCells, visiting)
    const right = evaluateAST(ast.right, sheet, evaluatedCells, visiting)

    if (isError(left)) return left
    if (isError(right)) return right

    if (['+', '-', '*', '/', '^'].includes(ast.op)) {
      const leftNum = toNumber(left)
      const rightNum = toNumber(right)

      if (leftNum.error) return createError(leftNum.error)
      if (rightNum.error) return createError(rightNum.error)

      const l = leftNum.value
      const r = rightNum.value

      switch (ast.op) {
        case '+':
          return l + r
        case '-':
          return l - r
        case '*':
          return l * r
        case '/':
          if (r === 0) return createError('DIV/0')
          const result = l / r
          if (!isFinite(result)) return createError('DIV/0')
          return result
        case '^':
          const powResult = Math.pow(l, r)
          if (!isFinite(powResult)) return createError('DIV/0')
          return powResult
      }
    }

    // Comparisons
    if (['=', '<>', '<', '<=', '>', '>='].includes(ast.op)) {
      // Determine comparison mode based on value types
      const leftPriority = getComparisonPriority(left)
      const rightPriority = getComparisonPriority(right)

      let cmp
      if (leftPriority === rightPriority) {
        if (typeof left === 'number' && typeof right === 'number') {
          cmp = left < right ? -1 : (left > right ? 1 : 0)
        } else if (typeof left === 'string' && typeof right === 'string') {
          cmp = left < right ? -1 : (left > right ? 1 : 0)
        } else if (isBoolean(left) && isBoolean(right)) {
          const lv = left.value ? 1 : 0
          const rv = right.value ? 1 : 0
          cmp = lv < rv ? -1 : (lv > rv ? 1 : 0)
        } else {
          cmp = 0 // Same value
        }
      } else {
        cmp = leftPriority < rightPriority ? -1 : 1
      }

      const result = 
        ast.op === '=' ? cmp === 0 :
        ast.op === '<>' ? cmp !== 0 :
        ast.op === '<' ? cmp < 0 :
        ast.op === '<=' ? cmp <= 0 :
        ast.op === '>' ? cmp > 0 :
        ast.op === '>=' ? cmp >= 0 :
        false

      return createBoolean(result)
    }

    return createError('ERR')
  }

  if (ast.type === 'call') {
    return evaluateCall(ast.name, ast.args, sheet, evaluatedCells, visiting)
  }

  return createError('ERR')
}

function evaluateCell(col, row, sheet, evaluatedCells, visiting) {
  const key = `${col},${row}`

  // Check if already evaluated
  if (evaluatedCells.has(key)) {
    return evaluatedCells.get(key)
  }

  // Check for cycle
  if (visiting.has(key)) {
    return createError('CYCLE')
  }

  // Mark as visiting
  visiting.add(key)

  let value
  const cell = sheet.getCell(col, row)
  if (!cell) {
    // Undeclared cell is 0
    value = 0
  } else if (cell.isFormula) {
    // Evaluate formula
    const result = evaluateAST(cell.ast, sheet, evaluatedCells, visiting)
    value = result
  } else {
    // Parse literal
    value = parseLiteral(cell.content)
  }

  // Mark as visited (remove from visiting set)
  visiting.delete(key)

  // Cache the result
  evaluatedCells.set(key, value)
  return value
}

function parseLiteral(content) {
  if (content === '' || content === null) {
    return 0
  }

  // Check for error tokens
  const errorTokens = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
  if (errorTokens.includes(content)) {
    const code = content.substring(1, content.length - 1) // Remove # and !
    return createError(code)
  }

  // Check for boolean
  if (content === 'TRUE') {
    return createBoolean(true)
  }
  if (content === 'FALSE') {
    return createBoolean(false)
  }

  // Try to parse as number
  const num = parseFloat(content)
  if (!isNaN(num) && /^-?\d+(\.\d+)?$/.test(content.trim())) {
    return num
  }

  // Otherwise it's text
  return content
}

/**
 * Expand a range into an array of cell values
 */
function expandRange(range, sheet, evaluatedCells, visiting) {
  const values = []
  const startCol = Math.min(range.start.col, range.end.col)
  const endCol = Math.max(range.start.col, range.end.col)
  const startRow = Math.min(range.start.row, range.end.row)
  const endRow = Math.max(range.start.row, range.end.row)

  for (let col = startCol; col <= endCol; col++) {
    for (let row = startRow; row <= endRow; row++) {
      const value = evaluateCell(col, row, sheet, evaluatedCells, visiting)
      values.push(value)
    }
  }

  return values
}

/**
 * Get all cells referenced in an argument (for collecting dependencies)
 */
export function getReferencedCells(ast, sheet) {
  const cells = new Set()

  function traverse(node) {
    if (!node) return

    if (node.type === 'cell') {
      cells.add(`${node.col},${node.row}`)
    } else if (node.type === 'range') {
      const startCol = Math.min(node.start.col, node.end.col)
      const endCol = Math.max(node.start.col, node.end.col)
      const startRow = Math.min(node.start.row, node.end.row)
      const endRow = Math.max(node.start.row, node.end.row)

      for (let col = startCol; col <= endCol; col++) {
        for (let row = startRow; row <= endRow; row++) {
          cells.add(`${col},${row}`)
        }
      }
    } else if (node.type === 'unary') {
      traverse(node.expr)
    } else if (node.type === 'binop') {
      traverse(node.left)
      traverse(node.right)
    } else if (node.type === 'call') {
      for (const arg of node.args) {
        traverse(arg)
      }
    }
  }

  traverse(ast)
  return cells
}

/**
 * Evaluate a function call
 */
function evaluateCall(name, args, sheet, evaluatedCells, visiting) {
  const functions = {
    'SUM': evaluateSUM,
    'MIN': evaluateMIN,
    'MAX': evaluateMAX,
    'COUNT': evaluateCOUNT,
    'AVG': evaluateAVG,
    'ABS': evaluateABS,
    'IF': evaluateIF
  }

  if (!(name in functions)) {
    return createError('NAME')
  }

  return functions[name](args, sheet, evaluatedCells, visiting)
}

function evaluateSUM(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let sum = 0
  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    for (const v of values.list) {
      sum += v
    }
  }

  return sum
}

function evaluateMIN(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let min = Infinity
  let found = false

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    if (values.list.length > 0) {
      found = true
      for (const v of values.list) {
        if (typeof v === 'number' && v < min) {
          min = v
        }
      }
    }
  }

  return found ? min : 0
}

function evaluateMAX(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let max = -Infinity
  let found = false

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    if (values.list.length > 0) {
      found = true
      for (const v of values.list) {
        if (typeof v === 'number' && v > max) {
          max = v
        }
      }
    }
  }

  return found ? max : 0
}

function evaluateCOUNT(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let count = 0

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting, true) // allowErrors=true
    if (values.list) {
      for (const v of values.list) {
        if (typeof v === 'number') {
          count++
        }
      }
    }
  }

  return count
}

function evaluateAVG(args, sheet, evaluatedCells, visiting) {
  if (args.length === 0) return createError('ERR')

  let sum = 0
  let count = 0

  for (const arg of args) {
    const values = collectValues(arg, sheet, evaluatedCells, visiting)
    if (values.error) return values.error
    for (const v of values.list) {
      if (typeof v === 'number') {
        sum += v
        count++
      }
    }
  }

  if (count === 0) return 0
  return sum / count
}

function evaluateABS(args, sheet, evaluatedCells, visiting) {
  if (args.length !== 1) return createError('ERR')

  const value = evaluateAST(args[0], sheet, evaluatedCells, visiting)
  if (isError(value)) return value

  const numResult = toNumber(value)
  if (numResult.error) return createError(numResult.error)

  return Math.abs(numResult.value)
}

function evaluateIF(args, sheet, evaluatedCells, visiting) {
  if (args.length !== 3) return createError('ERR')

  const condition = evaluateAST(args[0], sheet, evaluatedCells, visiting)
  if (isError(condition)) return condition

  // Determine truthiness
  let isTruthy
  if (isBoolean(condition)) {
    isTruthy = condition.value
  } else if (typeof condition === 'number') {
    isTruthy = condition !== 0
  } else if (typeof condition === 'string') {
    isTruthy = false
  } else {
    isTruthy = false
  }

  // Evaluate only the branch we take
  if (isTruthy) {
    return evaluateAST(args[1], sheet, evaluatedCells, visiting)
  } else {
    return evaluateAST(args[2], sheet, evaluatedCells, visiting)
  }
}

/**
 * Collect values from an argument (may be a range or expression)
 */
function collectValues(arg, sheet, evaluatedCells, visiting, allowErrors = false) {
  if (arg.type === 'range') {
    const values = expandRange(arg, sheet, evaluatedCells, visiting)
    // For non-COUNT functions, check for errors
    if (!allowErrors) {
      for (const v of values) {
        if (isError(v)) return { error: v }
        const numResult = toNumber(v)
        if (numResult.error) return { error: createError(numResult.error) }
      }
    }
    // Convert to numbers for non-COUNT functions
    if (!allowErrors) {
      const nums = []
      for (const v of values) {
        if (typeof v === 'number') nums.push(v)
        else if (isBoolean(v)) nums.push(v.value ? 1 : 0)
      }
      return { list: nums }
    }
    return { list: values }
  }

  const value = evaluateAST(arg, sheet, evaluatedCells, visiting)
  if (isError(value)) {
    if (allowErrors) return { list: [value] }
    return { error: value }
  }

  if (!allowErrors) {
    const numResult = toNumber(value)
    if (numResult.error) return { error: createError(numResult.error) }
    return { list: [numResult.value] }
  }

  return { list: [value] }
}

