/**
 * Sheet class for storing and managing cells
 */

import { parseFormula } from './formula-parser.js'

export class Sheet {
  constructor() {
    this.cells = new Map() // key: "col,row"
  }

  /**
   * Add a cell to the sheet
   */
  setCell(col, row, content, isFormula) {
    const key = `${col},${row}`
    let ast = null
    if (isFormula) {
      const result = parseFormula(content)
      ast = result.ast
    }
    this.cells.set(key, { content, isFormula, ast })
  }

  /**
   * Get a cell from the sheet
   */
  getCell(col, row) {
    const key = `${col},${row}`
    return this.cells.get(key)
  }

  /**
   * Get all declared cells
   */
  getAllCells() {
    const result = []
    for (const [key, cell] of this.cells) {
      const [col, row] = key.split(',').map(Number)
      result.push({ col, row, cell })
    }
    // Sort by column, then by row
    result.sort((a, b) => {
