/**
 * The declared cells of a sheet.
 */

import { parseFormula } from './formula-parser.js'

export class Sheet {
  constructor() {
    this.cells = new Map()
  }

  set(col, row, content) {
    const formula = content.startsWith('=')
    const ast = formula ? parseFormula(content.slice(1)) : null
    this.cells.set(`${col},${row}`, { col, row, content, formula, ast })
  }

  get(col, row) {
    return this.cells.get(`${col},${row}`)
  }

  /** Every declared cell, in ascending column and then ascending row order. */
  all() {
    return Array.from(this.cells.values()).sort((a, b) =>
      a.col !== b.col ? a.col - b.col : a.row - b.row
    )
  }
}

